  PAGES.push({
    id: "economy", title: "Экономика", sub: "Строительство, методы, корпорации и госзаказы", sections: [
      { id: "intro", title: "Развитие в мире после Великой ошибки", html:
        "<p>Уцелевшая цивилизация собралась внутри укреплённых мегаполисов. За их стенами лежат радиоактивные пустоши, затопленные равнины и полудикие земли. Выживание и рост государства подчиняются экономико-географическим и производственным правилам: строительству, модернизации методами и работе с корпорациями через госзаказы.</p>" +
        WORLD("Сейчас безопасная земля внутри стен стоит дороже золота, а выход в пустоши рискован. Поэтому одни страны растут вширь за счёт мегапроектов, а другие вглубь: методами и модернизацией.") },
      { id: "territory", title: "Территории", html:
        "<p>Любое строительство привязано к одному из двух типов территорий:</p>" +
        T(["Тип", "Что это", "Что размещают"], [
          ["<b>Мегаполис</b>", "Плотно застроенный городской массив за стенами и куполами. Здесь основной труд, научные центры (ЕНИ) и высокотехнологичное производство. Площадь крайне дефицитна.", "Заводы, научные центры, жильё, аркологии."],
          ["<b>Провинция</b>", "Внешний регион государства: пустоши, побережья, уцелевшие равнины, ресурсные зоны.", "Добыча, очистные сооружения, аграрные зоны, логистические узлы."]
        ]) +
        "<p>На карте сайта: «мегаполисом» считается город типа «Мегаполис» или «Агломерация» (от 5 млн жителей), а провинции — это 794 провинции карты. Любой другой город — часть провинции, где он стоит.</p>" +
        "<p>По умолчанию все сооружения государственные. В странах со смешанной или рыночной экономикой часть объектов принадлежит автономным корпорациям, которые сами занимают свободную площадь.</p>" },
      { id: "units", title: "Единицы и ресурсы", html:
        "<p>Сооружения потребляют и производят ресурсы в условных единицах (УЕ), задействуют трудовые ресурсы (ТЕ и КТЕ) и занимают полезную площадь. Определения:</p>" +
        GMN("в исходном документе значения не расписаны, определения предложил редактор.") +
        T(["Единица", "Определение"], [
          ["УЕ ресурсов", "Условные единицы потоков ресурсов. Классификация (природные ресурсы, продукты, особые) описана в разделе «Ресурсы»; затраты на стройки считаются в энергии, стройматериалах, металлах, механике, электронике, минералах и драгоценностях."],
          ["ТЕ", "Трудовая единица: 100 тыс. работников неквалифицированного труда."],
          ["КТЕ", "Квалифицированная трудовая единица: 100 тыс. специалистов. Даёт вдвое больше производства, чем ТЕ."],
          ["ЕПП", "Единица производственного потенциала: мощность страны, направляемая на стройку. Показатель страны, растёт с заводами и энергией."],
          ["Оплата труда", "1 кредит за 1 занятую ТЕ в ход (1 КТЕ — 2 кредита). Курс местных валют к кредиту указан в лоре, раздел «Валюты»."],
          ["ЕНИ (НИП)", "Научно-исследовательский потенциал. Рождается в научных центрах мегаполисов и на высокотехнологичных производствах, тратится на методы и технологии."]
        ]) },
      { id: "os", title: "Очки строительства и приоритеты", html:
        "<p>Темп стройки определяют <b>очки строительства (ОС)</b>. Они не копятся: каждый ход возникают из ЕПП и оплаты труда.</p>" +
        "<p class=\"m-formula\">1 ЕПП + рыночная оплата труда в валюте = 30 ОС</p>" +
        "<ol><li>В начале хода все ОС делятся поровну между всеми запущенными стройками.</li>" +
        "<li>Игрок может назначить приоритетные стройки. Каждая стоит 2 АВ за ход.</li>" +
        "<li>Приоритетные стройки получают +30% ОС, неприоритетные получают −20%.</li></ol>" +
        "<p><b>Пример.</b> Страна купила 600 ОС, идёт 5 строек, 1 из них приоритетная. Поровну выходит по 120 ОС. Приоритетная получает 120 × 1,3 = 156 ОС, остальные четыре по 120 × 0,8 = 96 ОС. Стоимость приоритета: 2 АВ.</p>" },
      { id: "buildings", title: "Классификация сооружений", html:
        "<p>Все объекты делятся на пять масштабов. Затраты записаны в УЕ как (энергия; сырьё; оборудование; стройматериалы; редкие элементы).</p>" +
        T(["Категория", "Масштаб в сеттинге", "Затраты (УЕ)", "ОС", "Контроль", "Площадь"], [
          ["1. Постройка", "Сектор мегаполиса или укреплённый аванпост. Обычно промежуточное звено цепочек.", "(1; 4; 2; 5; 1)", "100–250", "Минимальный надзор", "1"],
          ["2. Крупная постройка", "Промышленный узел, крупный жилой блок или аркология масштаба среднего довоенного города.", "(2; 6; 3; 7; 2)", "200–500", "Умеренная нагрузка на логистику", "2"],
          ["3. Сооружение", "Комплекс с элементами градостроительства: промышленный район мегаполиса, укрепрайон.", "(3; 8; 3; 9; 2)", "400–1000", "Серьёзный административный контроль", "4"],
          ["4. Крупное сооружение", "Объект стратегического значения: энергокаскады, дамбы, большие очистные станции. Много ТЕ.", "(3; 8; 4; 10; 3)", "800–2000", "Строгий контроль, иначе аварии, саботаж, кризисы", "8"],
          ["5. Мегасооружение", "Проекты, меняющие географию регионов: трансконтинентальные барьеры, глобальная дезактивация, орбитальные комплексы.", "от (4; 12; 5; 14; 3), индивидуально", "1600–10000", "Индивидуальные сроки, ресурсы и этапы", "16 и более"]
        ]) +
        GMN("Столбец «Площадь» — добавлена редактором (ячейки застройки). Остальное взято из документа.") },
      { id: "mods", title: "Модификаторы сроков", html:
        "<p>Нужное количество ОС корректируют два фактора.</p>" +
        "<h3>Коэффициент условий территории (КУТ)</h3>" +
        "<p>Разброс ОС от нижней границы к верхней определяется состоянием провинции или мегаполиса: радиацией, затоплением, рельефом, климатом, сохранностью грунта. Нижняя граница — самые безопасные участки. ОС = нижняя граница × КУТ.</p>" +
        T(["Состояние участка", "КУТ"], [
          ["Мегаполис за стенами, подготовленный участок", "1,0"],
          ["Обычная провинция", "1,25"],
          ["Затопленная или заболоченная", "1,5"],
          ["Радиоактивная пустошь", "1,8"],
          ["Зона заражения", "2,2"],
          ["Эпицентр удара или тяжёлое заражение", "2,5"]
        ]) +
        "<p>Верхняя граница для категорий 1–4 — это нижняя × 2,5, так что КУТ 2,5 даёт максимум диапазона.</p>" +
        "<h3>Ресурсное снабжение</h3>" +
        "<p>Если стройке нужно 10 УЕ стройматериалов, а логистика привезла 7, поступающие ОС умножаются на 7/10 = 0,7. При избытке снабжения механизм работает в обратную сторону и ускоряет работы.</p>" },
      { id: "methods", title: "Методы производства", html:
        "<p>Метод — технологическое, управленческое или организационное решение, которое повышает выпуск, снижает расход сырья и энергии, уменьшает экологическую нагрузку или улучшает внутриполитические показатели без новой площади. Методы — главный инструмент «высокой экономики».</p>" +
        "<h3>Плюсы</h3><ul><li>Экономия дефицитной площади.</li><li>Долгосрочное снижение расхода УЕ и издержек.</li><li>Рост квалификации: ТЕ постепенно становятся КТЕ.</li></ul>" +
        "<h3>Риски</h3><ul><li>Рост маргиналов и безработицы при резкой автоматизации.</li><li>Высокая разовая цена переоснащения (ЕНИ и валюта) и переобучения.</li></ul>" +
        "<h3>Как действуют</h3>" +
        "<ul><li><b>Структурная замена:</b> метод перестраивает цепочку и меняет одни ресурсы на другие (перевод завода с ископаемого топлива на чистую энергию, замкнутый цикл водоочистки).</li>" +
        "<li><b>Коэффициентная коррекция:</b> метод накладывает процентные модификаторы на производственные и экологические параметры.</li></ul>" +
        "<p>Стоимость метода: k — уровень метода по шкале технологий 1–10:</p>" +
        "<p class=\"m-formula\">ЕНИ = 10 × k · Валюта = 20 × k × категория объекта (кредитов)</p>" +
        WORLD("Уровни технологий в лоре уже расписаны от 1 до 10. Метод уровня выше технологического уровня страны недоступен.") },
      { id: "corps", title: "Корпорации", html:
        "<p>Корпорации — только неигровые структуры. Ими управляют логика игры и администрация, играть за корпорацию нельзя. Это автономные субъекты, которые действуют в рамках законов и строя страны. При жёстком плановом или тоталитарном строе с полной национализацией частных корпораций нет вообще.</p>" +
        "<p>В зависимости от экономической свободы корпорация может сама:</p>" +
        "<ul><li>строить собственные сооружения в мегаполисах и провинциях;</li><li>внедрять методы;</li><li>осваивать пограничные участки пустошей и затопленных провинций;</li><li>при предельно либеральном рынке содержать частные военизированные формирования для охраны активов.</li></ul>" +
        "<p>Мощь корпорации держится на её сооружениях. Они работают по тем же правилам, что государственные, но продукция и сырьё идут через локальные и глобальные рынки либо по прямым контрактам, а не по директивной цепочке.</p>" +
        WORLD("В лоре 53 корпорации: от ARC и Morgan Industries до Kurogane Holdings, Tianjian Arms и Nautilus Clique. Их присутствие в странах описано в статьях о корпорациях.") },
      { id: "orders", title: "Госзаказы и тендеры", html:
        "<p>Корпорация может работать на собственную прибыль либо выполнять <b>госзаказ</b> — целевую аренду её производственных мощностей и конструкторских бюро за бюджетные средства.</p>" +
        "<ul><li><b>Прямой госзаказ:</b> гарантирует корпорации быструю прибыль и сбыт, а государство получает нужные товары (модули, юниты, снабжение, спецтехнику) без затрат АВ на собственные заводы.</li>" +
        "<li><b>Конкурс (тендер):</b> правительство даёт требования нескольким профильным корпорациям, выбирает лучший проект и выкупает его крупной партией.</li></ul>" +
        "<h3>Формат в экономических приказах</h3>" +
        T(["Вид", "Шаблон"], [
          ["Прямой заказ", "«Государство [название] размещает у корпорации [название] заказ на производство [название продукта] сроком на [число] ходов»."],
          ["Конкурс", "«Государство [название] объявляет конкурс между корпорациями [список] на выполнение госзаказа. Участники должны представить проект/продукт [название] в течение [число] ходов»."]
        ]) },
      { id: "risks", title: "Риски потери контроля", html:
        "<ul><li><b>Деформация рынков:</b> картели, демпинг и сговоры роняют качество и разрушают цены.</li>" +
        "<li><b>Угроза суверенитету:</b> без контроля корпорация может работать с враждебным государством, выводить капитал и подрывать экономику изнутри.</li></ul>" +
        "<p>Поэтому стратегия строится не только на прямом бюджетном строительстве, но и на разумном регулировании частного сектора. Его уровень задают повестки «Принципы собственности», «Экономическая модель» и «Борьба с коррупцией».</p>" },
      { id: "summary", title: "Сводка показателей", html:
        T(["Группа", "Ключевые параметры", "Назначение"], [
          ["1. Территориально-строительные", "Тип площадки; свободная площадь; категория объекта (1–5); КУТ", "Где можно строить, сколько ОС и УЕ нужно, насколько сложны работы."],
          ["2. Темпы строительства", "ЕПП; ОС (не копятся); АВ (2 за приоритет); +30% / −20%; ресурсное снабжение", "Скорость стройки, распределение мощностей, штрафы за дефицит."],
          ["3. Модернизация (методы)", "Активные методы; коэффициенты производства и расхода УЕ; цена в ЕНИ и валюте; сдвиг ТЕ → КТЕ и рост маргиналов", "Рост выпуска и снижение нагрузки без новой площади; плата переобучением и социальными рисками."],
          ["4. Корпоративные", "Доля частных сооружений; контроль над бизнесом; госзаказы и конкурсы; лояльность корпораций", "Автономность частного сектора, эффективность закупок, риск саботажа и рыночного кризиса."]
        ]) }
    ]
  });

