  PAGES.push({
    id: "resources", title: "Ресурсы", sub: "Природные ресурсы, продукты, кадры, экология, склады, рынки и зарплаты", sections: [
      { id: "about", title: "Основы ресурсной экономики", html:
        "<p>Любая экономика опирается на добычу, переработку и распределение ресурсов. По мере роста государств и корпораций аппетиты производства растут, а управление потоками требует денег и администрации, поэтому учёт строгий и автоматизированный.</p>" +
        "<p>Ресурсы не измеряются тоннами и баррелями. Важны <b>пропорции и распределение потоков</b>, поэтому учёт идёт в <b>условных единицах (УЕ)</b>: «мало» — 1, «средне» — 2, «много» — 3, «очень много» — 4. УЕ разных ресурсов не равны друг другу. Так сглаживаются мелкие колебания, например временная нехватка людей из-за болезни.</p>" +
        T(["Категория", "Что это"], [["Природные ресурсы", "Неразработанное сырьё: нужна добыча."], ["Продукты", "Добытое сырьё и результат его переработки, готовый к использованию."], ["Особые ресурсы", "Системные показатели смежных механик: загрязнение, кадры, НИП, товары."]]) +
        WORLD("Ресурсы мира после Великой ошибки размечены по провинциям Земли. Пустыни, затопленные земли и зоны заражения дают меньше, а некоторые участки закрыты радиацией.") },
      { id: "natural", title: "Природные ресурсы", html:
        "<p>Освоение требует добывающих комплексов и технологий, повышающих выход сырья и снижающих вред природе. Доступность зависит от особенностей региона Земли.</p>" +
        T(["Ресурс", "Что это"], [["Залежи", "Неразработанные источники топлива: угольные пласты, нефтяные и газовые месторождения."], ["Породы", "Необработанные минеральные скопления, соли и каменные массивы."], ["Рудные жилы", "Залежи металлических руд."]]) +
        "<h3>Исчерпаемость</h3><p>Исчерпаемы залежи, породы, рудные жилы, флора и фауна, воздух и вода. При активной добыче участок (биом) истощается: месторождения становятся «бедными», а водные и органические зоны могут исчезнуть совсем. Скорость зависит от освоения региона и загрязнения.</p>" +
        "<h3>Статистика</h3><p>Общий ресурсооборот (производство плюс потребление) виден на главном экране государства. Подробный отчёт по региону, рынку или корпорации запрашивается экономическим приказом: «Требуется отчёт о ресурсах: [название объекта]».</p>" },
      { id: "products", title: "Продукты", html:
        "<p>Продукты получают переработкой природных ресурсов или других продуктов. Сооружения при переработке обычно потребляют больше УЕ, чем выпускают, поэтому цепочки окупаются только готовыми товарами.</p>" +
        T(["Продукт", "Что это"], [["Флора и фауна", "Неосвоенная живая природа."], ["Воздух и вода", "Основа жизни; критичны и для земных регионов, и для будущих внеземных баз."], ["Продовольствие", "Питание населения."], ["Товары народного потребления", "Мебель, лекарства, связь, личный транспорт: комфорт и быт."], ["Стройматериалы", "Органическое и неорганическое сырьё для сооружений."], ["Минералы", "Химические соли и элементы для промышленности."], ["Драгоценности", "Редкие вещества для высокоточной индустрии и роскоши."], ["Металлы", "Выплавленные сплавы."], ["Взрывчатые вещества", "Соединения взрывного действия."], ["Электроника", "Компоненты, передающие энергию и управляющие системами."], ["Механика", "Узлы и детали, дающие конструкциям физическую работу."], ["Топливо", "Энергоносители для тепла и энергии."], ["Энергия", "Электрические мощности для инфраструктуры и предприятий."]]) +
        GMN("Расчёт подключён в калькуляторе: рецепты (мощность, расход, потребители) лежат в data/calc.json → products. Прежние пять видов УЕ заменены этой классификацией: энергия → энергия; сырьё → металлы; оборудование → механика и электроника; стройматериалы → стройматериалы; редкие элементы → драгоценности и минералы.") },
      { id: "special", title: "Особые ресурсы", html:
        "<h3>Экологическая нагрузка</h3><p>Комплексный показатель деградации среды: химические выбросы, эрозия почв, обмеление водоёмов, эпидемии, истощение недр, радиационное и тепловое воздействие. Высокая нагрузка каждый ход создаёт риск негативных очагов, например зон радиационной пыли (они сами усиливают загрязнение) или смога. Очаги требуют ресурсов на сдерживание и вызывают события.</p>" +
        "<ul><li>Модернизация производств в пользу экологичных и наукоёмких технологий.</li><li>Очистительные кампании: полная ликвидация очага дорога, а перенос отходов только перекладывает проблему на другие территории.</li><li>Очистные сооружения, постоянно снижающие выбросы.</li></ul>" +
        "<h3>Трудовые кадры (ТК)</h3><p>Работоспособное население как ресурс экономики. Общая численность населения — политический показатель, ТК — экономический. Через ТК идут потребность предприятий в людях, миграция, рынок труда и социальная мобильность.</p>" +
        T(["Кадры", "Что это"], [["ТК", "Базовое работоспособное население (в калькуляторе: ТЕ)."], ["СТК", "Квалифицированные специалисты (КТЕ)."], ["ВТК", "Неквалифицированный военный и силовой персонал."], ["СВТК", "Профессиональные военные и технические специалисты силовых структур."], ["РН", "Резерв населения: прирост, которому ещё не хватило жилья и рабочих мест. Чтобы стать ТК, нужен жилой фонд."]]) +
        "<h3>Научно-исследовательский потенциал (НИП)</h3><p>Научная мощь государства. Вырабатывается исследовательскими центрами и передовыми производствами, выдаётся за события. Тратится на изучение технологий и поддержание наукоёмких производств (в «Экономике» тот же показатель назван ЕНИ).</p>" +
        "<h3>Товары</h3><p>Конечный результат цепочек: техника, услуги, уникальные изделия, роскошь. Производятся профильными предприятиями, торгуются на локальных рынках и влияют на внутреннюю политику (цена, спрос, идеология государства).</p>" +
        T(["Тип", "Что это"], [["Сюжетные (РП) объекты", "Изделия, нужные для участия в событиях."], ["Модули", "Снаряжение армии, элементы техники и будущих космических аппаратов."], ["Юниты", "Боевые единицы и подразделения, комплектуемые модулями."], ["Единицы снабжения", "Комплекты обеспечения боеспособности войск."]]) },
      { id: "logistics", title: "Склады и транспортные пути", html:
        "<h3>Склады</h3><p>Различаются типом, вместимостью, условиями эксплуатации и площадью. Запасы копятся только при рыночном переизбытке. Склады страхуют экономику от кризисов и снижают рыночные цены.</p><p>К началу 2200 года на складах каждой страны лежит запас на год: четыре хода нужд населения, заводов и армии и два хода строек. Исключение — нехватка, о которой прямо пишут статьи страны: её запасом не закрывали.</p>" +
        "<h3>Транспортные пути</h3><p>Постоянные логистические маршруты. Цена прокладки и содержания считается отдельно по технологиям и протяжённости.</p>" +
        T(["Путь", "Где действует", "Что нужно"], [["Локальный", "Внутри государства, союза или альянса. Соединяет регионы; объединяет их в единый локальный рынок.", "Торговые узлы на концах."], ["Глобальный", "Между государствами, может разветвляться. Объединяет локальные рынки в глобальный.", "Торговый узел международного класса (биржи, валютный обмен, высокая пропускная способность) в каждой точке подключения."]]) +
        GMN("в калькуляторе: один склад на страну (излишки копятся, дефициты покрываются), у пути — пошлина и пропускная способность. Торговые узлы и маршруты по отдельности не моделируются.") },
      { id: "expansion", title: "Модели расширения производства", html:
        T(["Строй", "Кто строит", "Как"], [["Плановая экономика", "Игрок: глава государства или министр экономики", "Решает, что и где строить, по данным ресурсооборота. План на любой срок, но с учётом людей и длительности строек (часто больше хода)."], ["Рыночная экономика", "Корпорации", "Предприятия развиваются сами и реинвестируют прибыль (выручка минус сырьё, зарплаты, налоги, акцизы, логистика). Корпорации выбирают выгодные рынки; успешные привлекают инвесторов через биржи и платят дивиденды."], ["Смешанная экономика", "Государство и корпорации", "Государственные объекты строятся по приказу игрока, частные по законам рынка; государство может директивой указать корпорациям, на каких рынках торговать."]]) + GMN("в калькуляторе: часть ОС идёт на новые заводы и энергоблоки по видам; государственная доля делится по плану страны (пусто — автоплан по приоритетам), частная — рынком по доходу на 1 ОС и привлекательности корпораций. Модель страны определяется долей частного сектора (до 20% плановая, до 60% смешанная, выше рыночная). Стройки копятся от хода к ходу.") },
      { id: "wages", title: "Заработные платы", html:
        "<p>В рыночном и смешанном секторах:</p>" +
        T(["Показатель", "Формула"], [["Средняя ожидаемая ЗП (страна)", "ВВП на душу × коэффициент заработных плат (зависит от уровня развития страны)"], ["Средняя реальная ЗП (страна)", "среднее всех фактических выплат; расхождение с ожидаемой влияет на социальные события"], ["Ожидаемая ЗП предприятия", "средняя ожидаемая ЗП + рыночный модификатор стоимости труда (спрос и предложение)"], ["Реальная ЗП предприятия", "МРОТ + эффективная надбавка − фактор убыточных зарплат"], ["Привлекательность компании", "реальная ЗП / ожидаемая ЗП; на неё умножаются эффективность сооружений и выпуск"]]) +
        "<p>Предприятия стремятся платить эффективную ЗП, а при нехватке прибыли снижают её до МРОТ. Если бизнес убыточен даже на МРОТ и не получает субсидий, он банкротится.</p>" +
        GMN("в калькуляторе корпорации страны считаются как предприятия: выручка, издержки, ожидаемая и реальная ЗП, МРОТ, привлекательность, банкротство. Государственный сектор и «прочий частный бизнес» — отдельные строки.") },
      { id: "markets", title: "Рынки и торговое регулирование", html:
        "<p>Единого «государственного» или «мирового» рынка нет: рынки делятся на локальные и глобальные.</p>" +
        "<h3>Локальные рынки</h3><p>Формируются в регионе или нескольких территориях, связанных локальными путями. Сюда стекаются ресурсы и товары государственных и частных предприятий зоны. Доступный объём природных ресурсов зависит от степени освоения территории: она растёт пассивно вместе с населением или быстрее, если строить геодезические и инфраструктурные объекты.</p>" +
        "<h3>Глобальные рынки</h3><ol><li>Подписать торговый договор.</li><li>Построить международные торговые узлы в отправных точках.</li><li>Разместить промежуточные пересадочные и ремонтные узлы на каждом участке маршрута.</li></ol>" +
        T(["Инструмент", "Что делает"], [["Протекционизм", "Прямое ограничение импорта и экспорта. Снижение барьеров открывает корпорациям дешёвое сырьё и внешние рынки, но повышает риск вытеснения отечественных компаний."], ["Санкции", "Запрет доступа конкретных товаров, ресурсов или производителей на рынок либо повышение транспортных тарифов."]]) +
        "<h3>Блокады</h3><ul><li><b>Физическая</b> — войска или флот перекрывают регион, блокируя все потоки и снабжение.</li><li><b>Санкционная</b> — законодательный запрет на оборот определённых ресурсов или товаров.</li><li><b>Иные ограничения</b> — любые нормативные барьеры по решению игрока.</li></ul>" +
        "<p>Цены пересчитываются каждые 2 хода по балансу спроса и предложения.</p>" +
        GMN("в калькуляторе: местные цены и один глобальный рынок для стран с торговым договором, протекционизм и пошлины. Санкции, физические блокады и иные ограничения вводит ГМ: запрет и надбавка к пошлине, перекрытие доли торговли и снабжения, квота. Вводящий теряет торговлю, платит за содержание блокады и теряет стабильность.") },
      { id: "summary", title: "Сводка показателей", html:
        T(["Группа", "Показатели", "Назначение"], [["Ресурсные и производственные", "УЕ; ресурсооборот; степень освоения; вместимость складов и запасы", "Потоки сырья, масштаб экономики, доля доступных ресурсов региона, демпфирование цен."], ["Кадровые и научные", "ТК, СТК, ВТК, СВТК; РН; НИП", "Работа предприятий и силовых структур, миграция, демографический резерв, темп технологий."], ["Экологические", "Загрязнение; шанс истощения биомов и месторождений", "Риск очагов, деградация территорий, скорость выработки."], ["Рыночные и торговые", "Цены (раз в 2 хода); баланс спроса и предложения; протекционизм %; тарифы и пропускная способность", "Стоимость, экспорт и импорт, доступность рынков."], ["Финансовые и зарплатные", "Прибыль корпорации; ожидаемая и реальная ЗП страны и предприятия; МРОТ и надбавка; привлекательность", "Рост частного сектора, банкротства, социальная напряжённость, выпуск."]]) }
    ]
  });

  // ================= АРМИЯ =================
  PAGES.push({
    id: "army", title: "Армия", sub: "Дивизии, эскадры, авиационные звенья, приказы и снабжение", sections: [
      { id: "intro", title: "Архитектура вооружённых сил", html:
        "<p>Каждому государству нужны регулярные вооружённые силы: против внешних агрессоров, пиратов и рейдеров, а также внутренних угроз. Что бы ни выбрала доктрина, основа армии — сухопутные и военно-морские силы, усиленные авиацией.</p>" +
        "<p>Один игровой ход равен <b>трём месяцам</b>. Конфликты затяжные, поэтому исход боя не решается только описанием. Вердикт по боевым приказам, особенно между игроками, выносится комплексно: по расчёту боевого калькулятора, броску кубика успеха и суждению администратора, который оценивает тактическую грамотность и логику действий.</p>" +
        WORLD("За стенами мегаполисов лежат пустоши и затопленные равнины, а океан стал главным путём между государствами. Поэтому армии воюют на ограниченном числе проходимых провинций, а контроль над морскими коридорами важен не меньше, чем над сушей.") },
      { id: "divisions", title: "Сухопутные дивизии", html:
        "<p>Дивизия — основная тактическая единица. Игрок оперирует дивизиями на карте: распределяет их по провинциям, строит линию фронта и отдаёт приказы о наступлении или отходе, по отдельности или в составе армий.</p>" +
        "<p>В дивизию могут входить разные рода войск, но тип ей присваивает калькулятор по итоговым характеристикам. Тип не запрещает манёвров, он определяет их эффективность.</p>" +
        T(["Тип", "Роль", "Сильна", "Уязвима"], [
          ["<b>Пехотная</b>", "Универсальная основа армии, действует малыми и крупными группами.", "Штурм мегаполисов, пересечённая местность.", "Огонь артиллерии и беспилотники."],
          ["<b>Артиллерийская</b>", "Огневое подавление пехоты, техники и укреплений.", "Против скоплений и укрепрайонов.", "Ближний бой."],
          ["<b>Техническая (бронетанковая)</b>", "Ударный кулак на открытой местности.", "Открытая местность, поддержка пехоты.", "Авиаудары, городская застройка, труднопроходимые провинции."],
          ["<b>Беспилотная</b>", "Массированные удары дронами по наземным целям.", "Любой рельеф.", "РЭБ, ПВО, пехота со специальным оснащением."],
          ["<b>Противовоздушная (ПВО)</b>", "Прикрытие от авиации и дронов.", "Против беспилотных дивизий и авиации.", "Любые наземные части в прямом столкновении."]
        ]) +
        "<p>У каждой дивизии может быть своё название по традициям государства. Ею командуют офицеры, выпускники военных академий. Соотношение типов на участке фронта определяет возможность окружений, котлов и прорывов.</p>" },
      { id: "attach", title: "Усиление дивизий", html:
        "<p>Дивизию можно усилить придаваемыми <b>батальонами и ротами</b> специального назначения: РЭБ, РХБЗ и другими. Усиливаются <b>только дивизии</b>. На эскадры это не распространяется: их особенности ГМ определяет сам по ролевым постам.</p>" +
        "<p>Придаваемые части не меняют тип дивизии, а добавляют ей бонусы и расход. Схема:</p>" +
        "<ul><li>В дивизию можно придать до 3 батальонов или рот.</li>" +
        "<li>Каждая придаваемая часть добавляет +0,5 ед. снабжения в ход и учитывается в расчёте медианы параметров.</li>" +
        "<li>Одноимённые части не складываются: второй батальон РЭБ даёт только половину бонуса.</li></ul>" +
        T(["Часть", "Что даёт дивизии"], [
          ["РЭБ (радиоэлектронной борьбы)", "Снижает урон беспилотников и повышает реагирование обороны против дронов."],
          ["РХБЗ (радиационной, химической и биологической защиты)", "Снимает штрафы за радиацию и заражение в пустошах и зонах заражения."],
          ["Инженерная", "Укрепления в обороне, штурм городской застройки."],
          ["Разведывательная", "Повышает реагирование обороны и точность оценки сил противника."],
          ["Связи", "Сокращает задержку управления при удалении от штаба."],
          ["Медицинская", "Ускоряет восстановление боеспособности в тылу."],
          ["Тыла и снабжения", "Снижает расход снабжения на 10%."],
          ["Противотанковая", "Повышает силу обороны против технических дивизий."]
        ]) +
        GMN("Список частей и бонусы добавлены редактором и утверждены автором.") },
      { id: "navy", title: "Военно-морской флот", html:
        "<p>Контроль над морскими коридорами в затопленном мире стратегически важен. Флот устроен как сухопутные силы:</p>" +
        "<ul><li><b>Эскадра</b> — тактический аналог дивизии, формируется из единичных боевых кораблей с верфей. Осваивает акватории, ведёт морские бои и способна массированно бить по прибрежным целям.</li>" +
        "<li><b>Флот</b> — крупное оперативное объединение эскадр (аналог армии), действует на глобальной карте.</li></ul>" +
        "<p>Усиление придаваемыми частями на эскадры не распространяется.</p>" },
      { id: "air", title: "Авиационные звенья", html:
        "<p>Авиация не образует отдельных наземных или морских дивизий. Она работает как <b>авиационное звено</b> разных классов: тактическое, стратегическое, штурмовое, истребительное и другие.</p>" +
        "<p>Звенья прикрепляются к наземным дивизиям, армиям, эскадрам и флотам. Они дают господство в воздухе и поддерживают основные силы точечными или массированными ударами на любой местности.</p>" },
      { id: "armies", title: "Армии, переброска, командование", html:
        "<h3>Оперативные объединения</h3>" +
        "<p>Армия объединяет от 5 до 10 дивизий и более (флот — несколько эскадр). По умолчанию одна армия занимает одну провинцию. Приказами перемещения и прорыва армия может разделяться, занимая соседние провинции до встречи с вражескими гарнизонами.</p>" +
        "<ul><li><b>Марш:</b> смена провинции дислокации, в том числе во время боя.</li><li><b>Погрузка и высадка:</b> переброска армии или отдельных дивизий морем или по воздуху.</li></ul>" +
        "<p>Для переброски крупных контингентов нужны транспортные суда в составе флота. Их число зависит от технологического уровня государства: чем сложнее техника, тем больше транспортов нужно. Формула:</p>" +
        "<p class=\"m-formula\">Транспортов на дивизию = 2 + ⌊технологический уровень / 2⌋</p>" +
        "<p>Пример: при уровне 5 на одну дивизию нужно 4 транспорта.</p>" +
        "<h3>Командование и связь</h3>" +
        "<ul><li>Армии и флоты возглавляют командующие (NPC или персонажи игроков), они дают боевые бонусы и компенсируют ограничения связи.</li>" +
        "<li><b>Задержка управления:</b> чем дальше армия от главного или оперативного штаба, тем позже доходят приказы при внезапном контакте.</li>" +
        "<li><b>Персонаж-командир военного класса</b> берёт управление без задержки и сам становится оперативным штабом, сокращая дистанцию связи для соседних группировок.</li>" +
        "<li><b>Доктрины:</b> если удалённую армию или флот не ведёт персонаж, при задержке связи они действуют автономно под управлением администрации по шаблонам, которые игрок утвердил заранее.</li></ul>" },
      { id: "stats", title: "Параметры подразделений", html:
        "<p>Эффективность дивизии или эскадры складывается из набора параметров. Параметры атаки и обороны — число от 1 до 100, проценты — от 0 до 100.</p>" +
        T(["Параметр", "Что значит", "Шкала"], [
          ["<b>Боеспособность</b>", "Главный индикатор: живая сила, исправность техники, обеспечение. Падает в бою и пассивно на линии фронта (диверсии, ДРГ, стычки). В тылу восстанавливается, поэтому нужна ротация.", "0–100 %"],
          ["Протяжённость обороны", "Ширина фронта, которую часть способна прикрыть.", "1–100"],
          ["Сила обороны", "Стойкость и огневая мощь при удержании позиций.", "1–100"],
          ["Реагирование обороны", "Скорость ответа на внезапные действия, критично против дронов и мобильных частей.", "1–100"],
          ["Масштаб атаки", "Охват территории, на которой пробуют прорыв.", "1–100"],
          ["Мощь атаки", "Совокупный наступательный потенциал.", "1–100"],
          ["Стремительность атаки", "Скорость развёртывания и плотность удара; эффективна против стойкой, но неповоротливой обороны.", "1–100"],
          ["Требуемое снабжение", "Единицы снабжения за ход (три месяца).", "ед./ход"],
          ["Профессионализм", "Опыт растёт с приказами, учениями и боями; падает при пополнении потерь новобранцами.", "0–100 %"],
          ["Моральное состояние", "Боевой дух: риск дезертирства и сдачи в плен. Каждый ход умножается на модификатор от соотношения сил в соседних провинциях и успеха прошлого приказа; потолок 100%.", "0–100 %"]
        ]) +
        "<p>Потери армии распределяются между дивизиями пропорционально их типу и составу сил противника.</p>" },
      { id: "calc", title: "Расчёт армии и приказы", html:
        "<p>Показатели армии или флота собираются из показателей входящих в них частей:</p>" +
        "<ul><li>Требуемое снабжение суммируется.</li><li>Боеспособность считается как среднее арифметическое.</li><li>Параметры атаки и обороны считаются по формуле:</li></ul>" +
        "<p class=\"m-formula\">Итог = медианное значение × (1 + число дивизий / 100)</p>" +
        "<p><b>Пример.</b> У восьми дивизий медиана мощи атаки 40. Итог: 40 × (1 + 8/100) = 43,2.</p>" +
        "<p>Приказ меняет параметры армии. Качественный игровой пост к приказу может усилить любые характеристики, кроме снабжения и профессионализма. Размеры изменений:</p>" +
        T(["Приказ", "Что меняет"], [
          ["Прорыв", "Масштаб и мощь атаки +30%."],
          ["Глухая оборона", "Протяжённость и сила обороны +30%."],
          ["Удержание позиции", "Масштаб и мощь атаки −10%; стремительность сохраняется."],
          ["Поддержка", "+5% от всех параметров атаки и обороны ко всем союзным приказам удержания, обороны и прорыва в радиусе 2 провинций."],
          ["Артобстрел", "Стремительность и мощь атаки +30%; масштаб атаки и сила обороны −30%."],
          ["Перемещение", "Боевые параметры не меняются."]
        ]) +
        GMN("Значение поддержки (5%, радиус 2 провинции) взято из документа. Остальные проценты добавлены редактором и утверждены автором.") },
      { id: "matrix", title: "Матрица противодействия", html:
        "<p>В столкновении состав сил определяет, кто получает основной урон:</p>" +
        T(["Наносит повышенный урон", "Кому"], [
          ["Авиационные звенья", "Артиллерии"], ["Артиллерия", "Технике"], ["Беспилотники", "Пехоте"],
          ["ПВО", "Авиационным звеньям и беспилотникам"], ["Техника", "ПВО"]
        ]) +
        "<p>Урон по уязвимому типу ×1,5. У пехоты и беспилотных дивизий нет вторичной цели.</p>" },
      { id: "tech", title: "Комплектация и технологический уровень", html:
        "<p>Каждая дивизия и каждый корабль эскадры собираются из модулей. Итоговые характеристики калькулятор считает как медиану параметров: личного состава (подготовка, мотивация), индивидуального снаряжения, вооружения, бронетехники и прикреплённых авиационных звеньев.</p>" +
        "<p>Жёсткого древа технологий нет. Вместо него есть приблизительный технологический уровень государства (шкала 1–10) с примерами доступных образцов. Рост уровня открывает лучшие модули, но высокотехнологичные войска заметно дороже в производстве, обучении и снабжении.</p>" +
        "<p>Поэтому приходится выбирать долгую доктрину: массовая дешёвая армия для войн на истощение или компактные элитные силы для быстрых кампаний.</p>" },
      { id: "supply", title: "Снабжение", html:
        "<p>Дивизия, авиационное звено или корабль нуждается в боеприпасах, топливе, запчастях и еде. Единицы снабжения производят предприятия ВПК, они поступают на локальные рынки, и армия с флотом закупают их каждый ход. Вне национальных рынков нужна защищённая линия снабжения от границ к театру военных действий. Без снабжения части быстро теряют боеспособность и мораль.</p>" +
        "<p>База: пехотная дивизия с лёгким транспортом тратит <b>2 ед.</b> в ход. Для других типов:</p>" +
        T(["Тип", "Снабжение, ед./ход"], [["Пехотная", "2"], ["Артиллерийская", "3"], ["Техническая", "4"], ["Беспилотная", "3"], ["Противовоздушная", "3"], ["Авиационное звено", "2"]]) +
        "<h3>Модификаторы расхода</h3>" +
        "<p>Накладываются на среднее значение всех модулей части:</p>" +
        T(["Условие", "Множитель"], [["Призывная армия в мирное время", "× 0,5"], ["Флот за пределами государственных границ", "× 2"], ["Армия в боях на чужой территории", "× 3"]]) +
        "<p>Навыки командующего могут снижать или повышать расход.</p>" },
      { id: "reserve", title: "Консервация флота", html:
        "<p>Без снабжения флот деградирует даже в портах. Чтобы не тратиться на содержание кораблей в мирное время, государство может поставить их на консервацию:</p>" +
        "<ul><li>Потребность в снабжении и финансировании падает в 5 раз.</li>" +
        "<li>Постановка занимает 1 ход (три месяца), снятие — 2 хода (шесть месяцев).</li>" +
        "<li>На время постановки, снятия или модернизации каждый корабль занимает 1 профильный стапель, поэтому консервация большого флота может затянуться.</li></ul>" },
      { id: "summary", title: "Сводка показателей", html:
        T(["Группа", "Ключевые параметры", "Назначение"], [
          ["1. Организационно-структурные", "5 типов дивизий; усиливающие батальоны и роты; эскадры; авиационные звенья; армии (5–10+ дивизий) и флоты; технологический уровень", "Состав сил, доступные модули, матрица противодействия, масштаб соединений на карте."],
          ["2. Боевые", "Боеспособность; оборона (протяжённость, сила, реагирование); атака (масштаб, мощь, стремительность); профессионализм; мораль", "База для калькулятора боя, агрегируется в показатели армии."],
          ["3. Управление и разрешение боя", "Приказы; задержка связи; персонаж-командир; доктрины; вердикт (калькулятор, кубик, суждение администратора)", "Скорость реакции, модификаторы, исход боёв между игроками."],
          ["4. Логистика и тыл", "Снабжение (база 2 ед.); модификаторы × 0,5 / × 2 / × 3; вместимость транспортов; консервация (÷5; 1 и 2 хода; стапели)", "Стоимость содержания, зарубежные кампании, ротация, сохранность флота."]
        ]) }
    ]
  });

  // ================= ВНЕШНЯЯ ПОЛИТИКА =================
  // Раздел переписан по рабочему тексту автора. Игра идёт на Земле (позже — в Солнечной системе), поэтому «планеты», «звёздные системы» и «квадранты»
  // заменены провинциями, городами и орбитальными объектами. Числа взяты из исходного текста без изменений.
  PAGES.push({
    id: "diplomacy", title: "Внешняя политика", sub: "Конфронтации, договоры, переговоры, съезды и международные организации", sections: [
      { id: "about", title: "О чём этот раздел", html:
        "<p>Здесь описано, как государство строит отношения с соседями: и с теми, кого ведут игроки, и с теми, кем управляет ГМ. Раздел объясняет, из чего складывается успех внешней политики, сколько она стоит в очках и как её итоги отражаются на внутренних и внешних показателях страны.</p>" +
        "<p>Основа всего — <a href=\"#wiki/mech/diplomacy/confrontations\">конфронтация</a>. Дальше идут <a href=\"#wiki/mech/diplomacy/balance\">расчёт её исхода</a> и <a href=\"#wiki/mech/diplomacy/treaties\">договоры</a>, которыми конфронтации обычно заканчиваются. В конце собраны <a href=\"#wiki/mech/diplomacy/indicators\">показатели</a>, на которых всё держится.</p>" +
        WORLD("Действие идёт на Земле. Спутники и орбитальные станции — такие же объекты спора, как города и провинции. Когда игра выйдет в Солнечную систему, расстояния для области конфронтации будут считаться уже в ней; до тех пор правила этого не предусматривают.") },

      { id: "confrontations", title: "Конфронтации", html:
        "<p>Конфронтация — столкновение интересов двух сторон. Повод может быть любым: от желания повоевать до итога долгой тайной игры двух сильных держав. Почти любая дипломатия, с войной или без неё, начинается именно с неё.</p>" +
        "<h3>Объект спора</h3>" +
        "<p>У каждой конфронтации есть объект: то, из-за чего идёт борьба. Это может быть вещь или понятие — провинция, город, мегаполис, орбитальная станция, спутниковая группировка, месторождение, технология, пленённый лидер. Одна сторона обязательно объектом не владеет и хочет его получить. Другая им владеет и удерживает его, либо тоже не владеет, но имеет на него свои виды.</p>" +
        "<h3>Две стороны и перекрёстные споры</h3>" +
        "<p>В одной конфронтации всегда две стороны. Если появляется третья сторона с полностью иными целями, возникают перекрёстные конфронтации: по одной на каждую пару. Три стороны дают три конфронтации, четыре стороны — шесть.</p>" +
        NOTE("Пример: одна держава владеет городом, вторая хочет его занять, третья — разрушить. Это три разные цели, значит, три конфронтации вокруг одного города.") +
        "<h3>Откуда берутся конфронтации</h3>" +
        "<ul><li>Игрок объявляет её сам.</li>" +
        "<li>Она возникает из действий игроков или из лора.</li>" +
        "<li>Её порождают события и прежние соглашения.</li>" +
        "<li>Она может быть заложена в лор государств: например, у держав, воевавших в Евро- и Китайско-американской войнах, к началу кампании остаётся несколько неулаженных споров.</li></ul>" +
        "<p>Конфронтация почти всегда кончается переговорами и договором, независимо от того, победил ли кто-то или всё закончилось вничью.</p>" +
        WORLD("После Великой ошибки спорят за то, что можно удержать: пригодные для жизни земли, мегаполисы под куполами, уцелевшие орбитальные станции. Поэтому объект спора почти всегда связан с землёй или с орбитой над ней.") },

      { id: "area", title: "Область и требования", html:
        "<h3>Область конфронтации</h3>" +
        "<p>Вокруг объекта спора очерчивается область конфронтации. Её центр — точка на карте, где находится объект (для орбитального объекта — точка на поверхности под ним). Исходный радиус — три провинции от центра.</p>" +
        "<ul><li>Любое государство внутри области может вступить в спор третьей стороной со своими целями и тем самым создать перекрёстную конфронтацию.</li>" +
        "<li>Оно может и встать на сторону одной из двух без приглашения. Требования в этом случае стоят вдвое дороже в очках влиятельности.</li>" +
        "<li>Область растёт сама по мере вложенных очков влиятельности. Чем больше требований и союзников, тем шире спор и тем сложнее миру его погасить.</li></ul>" +
        NOTE("Пример: одна страна предъявляет претензию на город, который держит другая. Объект спора — город, область — круг в три провинции вокруг него.") +
        "<h3>Требования</h3>" +
        "<p>Требование — любое условие, которое сторона хочет получить в итоге, включая сам объект спора. Требования станут пунктами договора, если эта сторона победит. Каждое требование — это новый предмет спора, купленный за очки влиятельности.</p>" +
        "<ul><li>Чем больше требований, тем весомее должна быть победа, чтобы противник согласился.</li>" +
        "<li>Каждое требование расширяет область конфронтации. Если сильная сторона выдвигает много выгодных себе требований, соседи в области могут встать на сторону слабой, чтобы никто не усилился слишком сильно.</li>" +
        "<li>Требования можно предъявлять не только к объекту спора и лидеру противника, но и ко всем, кто его поддержал: союзным государствам. Чем дольше спор и чем больше в нём участников, тем больше требований и тем шире конфликт.</li></ul>" +
        "<p>Так одним набором правил описываются локальные конфликты, войны через посредников и мировые войны.</p>" },

      { id: "invite", title: "Приглашение участников", html:
        "<p>Позвать в конфронтацию другое государство можно за очки влиятельности. Что нужно учесть:</p>" +
        "<ul><li>Вы сами выбираете, какие требования отдаёте приглашённому. Чем больше требований, интересных ему, вы передаёте, тем вероятнее согласие.</li>" +
        "<li>Противник может позвать того же участника. Тогда придётся предложить больше требований или договариваться другим путём.</li>" +
        "<li>Если участника позвали обе стороны и он отказал обеим, во внешней политике он считается пассивным. Его влиятельность падает на половину от суммы, потраченной обеими сторонами на приглашения.</li></ul>" },

      { id: "points", title: "Очки: влиятельность и АВ", html:
        "<p>Любое действие в конфронтации стоит очков двух видов.</p>" +
        "<ul><li><b>Влиятельность</b> — главный ресурс внешней политики: международная валюта страны. Копится и тратится как запас.</li>" +
        "<li><b>Административное влияние (АВ)</b> — внутренний ресурс управления: занятость аппарата в этот ход. Не копится, обновляется каждый ход.</li></ul>" +
        T(["Действие", "Влиятельность", "АВ"], [["Добавить требование", "5", "1"], ["Пригласить союзника", "5", "2"], ["Вступить без приглашения (третья сторона)", "10 (вдвое дороже)", "по действию"]]) +
        "<p>В горячей фазе обе цены удваиваются.</p>" +
        "<p>Остальные действия холодной фазы (конференции, переговоры, санкции) и горячей фазы (переброска флота и армий, мирные переговоры) тратят АВ по собственным правилам.</p>" },

      { id: "balance", title: "Расчёт конфронтации", html:
        "<p>Победителя определяет <b>баланс сил</b>. Он начинается с нуля и сдвигается к одной из сторон. Достигнув значения 100 или −100 (в зависимости от того, с какой стороны расчётной таблицы стоит государство), он приводит к победе: победитель предъявляет все требования в виде ультиматума. Если ультиматум не принят, начинается война за ультиматум.</p>" +
        "<h3>Четыре фазы</h3>" +
        "<p>Конфронтация может закончиться на любой фазе, проходить все подряд не обязательно.</p>" +
        T(["Фаза", "Длительность", "Усталость", "Цена действий"], [
          ["<b>Начальная</b>", "ровно 1 ход", "не набирается", "стандартная. Считается исходный баланс, приглашения союзников приносят баллы"],
          ["<b>Холодная</b>", "не ограничена", "стандартная", "стандартная. Стороны давят друг на друга дипломатией и экономикой; на поле боя — только редкие, чаще тайные стычки"],
          ["<b>Горячая</b>", "не ограничена", "двойная", "двойная в очках влиятельности и АВ. Стороны, не договорившись, пытаются заставить противника силой"],
          ["<b>Война за ультиматум</b>", "не ограничена", "победитель — двойная, проигравший — тройная", "Баланс возвращается к нулю и двигается только военными действиями. Исход войны определяет администратор по ходу ролевой игры, поэтому отдельных очков победы здесь нет"]
        ]) +
        "<h3>Исходный баланс</h3>" +
        T(["Источник", "Баллы"], [
          ["Приглашён союзник: мажорное государство", "+3"],
          ["Приглашён союзник: минорное государство", "+2"],
          ["Государственное присутствие (доля от 0 до 1), умноженное на 10", "от 0 до 10"],
          ["Мировая поддержка (доля от 0 до 1), умноженная на 10", "от 0 до 10"]
        ]) +
        NOTE("После начальной фазы баланс меняют только конкретные действия по этой конфронтации.") },

      { id: "moves", title: "Что двигает баланс", html:
        "<h3>Санкции</h3>" +
        "<p>Успешные санкции, снизившие материальное благосостояние противника или его союзников. Мерило — ВВП и бюджет государства. Оценка идёт на следующем ходу:</p>" +
        T(["Падение", "Баллы"], [["меньше 2%", "1"], ["меньше 4%", "2"], ["меньше 8%", "3"], ["больше 8%", "4"]]) +
        "<h3>Переговоры</h3>" +
        T(["Результат", "Баллы"], [
          ["Союзник противника отказался поддерживать его требования", "1"],
          ["Союзник противника поддержал часть ваших требований", "2"],
          ["Союзник противника перешёл на вашу сторону", "4"],
          ["Выросла мировая поддержка", "2"],
          ["Упала мировая поддержка противника", "1"],
          ["Заключён договор, удовлетворяющий часть ваших требований", "3"]
        ]) +
        "<h3>Бои</h3>" +
        T(["Событие", "Баллы"], [
          ["Выиграно крупное сражение: сухопутное, морское, воздушное или орбитальное", "1"],
          ["Захвачена провинция", "3"],
          ["Захвачен мегаполис или столица", "5"],
          ["Освобождена провинция", "2"],
          ["Освобождён мегаполис или столица", "4"]
        ]) +
        "<h3>Потери</h3>" +
        "<p>Воевать нужно экономно. За каждую потерянную (утратившую боеспособность) дивизию, эскадру или авиазвено сторона теряет баллы баланса. Сколько именно, зависит от повестки «Организация армии»:</p>" +
        T(["Преобладает", "Баллов за единицу", "Единиц за 1 балл"], [
          ["Поголовная служба", "0,1", "10"],
          ["Сословная служба", "0,2", "5"],
          ["Мобилизация", "0,5", "2"],
          ["Срочная служба", "0,75", "1,5"],
          ["Контрактная служба", "0,4", "2,5"],
          ["Частная контрактная служба", "0,2", "5"]
        ]) },

      { id: "fatigue", title: "Усталость от конфронтации", html:
        "<p>Второй показатель исхода — усталость. Она напрямую меняет шансы событий, которые снижают стабильность в провинциях и лояльность групп населения. Чем она выше, тем чаще приходят плохие события и тем труднее из них выбираться. Поэтому лучше не доводить дело до войны за ультиматум и искать дипломатический выход.</p>" +
        T(["Усталость", "Эффект на события"], [
          ["меньше 15%", "повышен шанс хороших событий"],
          ["15–45%", "обычные шансы хороших и плохих"],
          ["45–80%", "повышен шанс плохих"],
          ["80–100%", "повышен шанс плохих, понижен шанс хороших"],
          ["больше 100%", "шанс плохих сильно повышен, хороших понижен"]
        ]) +
        "<p>Настоящие последствия начинаются после 100%. С каждым следующим процентом падает стабильность во всех прифронтовых провинциях (в пределах двух провинций от линии фронта). Она падает и в провинциях, затронутых войной: где есть военные производства, центры мобилизации и подготовки армии, узлы снабжения. Размер падения зависит от того, насколько провинция вовлечена в войну.</p>" +
        NOTE("Плохие события при умелом управлении можно обратить себе на пользу.") },

      { id: "treaties", title: "Договоры", html:
        "<p>Договор — документ, в котором стороны признают требования друг друга. Он — итог переговоров, съездов, ультиматумов, судов и вообще любой дипломатии внутри конфронтации.</p>" +
        "<h3>Открытость</h3>" +
        "<ul><li><b>Публичный</b> — текст доступен всем.</li>" +
        "<li><b>Частично публичный</b> — открыта только та часть, которую назвал сам договор.</li>" +
        "<li><b>Тайный</b> — о нём даже не объявляют.</li></ul>" +
        "<p>Влияние договора зависит от его открытости и числа подписантов. Чем меньше сторон его признаёт, тем мягче последствия нарушения.</p>" +
        "<h3>Оформление</h3>" +
        "<p>Договор — текстовый файл любого формата, который открывается в Word или Google Документах. Он оформлен по шаблону с обязательными и необязательными пунктами:</p>" +
        "<ol><li>Название договора.</li><li>Государство-инициатор.</li><li>Все подписанты.</li><li>Дата подписания (игровая и реальная).</li><li>Срок действия.</li><li>Дата вступления в силу (игровая и реальная).</li><li>Цели и условия.</li><li>Наказания за нарушение условий.</li><li>Условия досрочного расторжения.</li><li>Условия вступления в договор того, кто его не подписывал.</li></ol>" +
        "<p>Цели выбирают подписанты. Подсказки:</p>" +
        "<ul><li>ненападение;</li><li>коллективная война;</li><li>совместные исследования;</li><li>экономическая поддержка;</li><li>совместная политика;</li><li>интеграция;</li><li>совместные проекты.</li></ul>" +
        "<p>Одни пункты в разных видах договоров обязательны, другие запрещены; это описано у каждого вида. Расширять пункты и добавлять свои можно свободно, главное — разумность. Администрация проверяет их по очереди.</p>" +
        "<h3>Нарушения</h3>" +
        "<ul><li>Нарушение между подписанием и вступлением в силу штрафов и конфронтаций не даёт. Но нарушитель становится уязвимее для вражеской пропаганды, если сознательность населения низкая.</li>" +
        "<li>Нарушение условий или наказаний (пункты «Наказания» и «Условия расторжения») запускает конфронтацию между нарушителем и остальными подписантами. Эти пункты и отдельно прописанные наказания становятся требованиями пострадавшей стороны автоматически.</li></ul>" +
        "<h3>Шаблоны</h3>" +
        "<p>Составлять договор с нуля необязательно. Для каждого вида есть готовый шаблон: достаточно вписать названия сторон и добавить свои пункты. Шаблоны лежат в форме для составления договоров; можно подать и собственный текст в её полях.</p>" },

      { id: "talks", title: "Переговоры", html:
        "<p>Переговоры — официальный акт между представителями двух государств. Их ход и итог зависят от администрации: если не зафиксировано, то не было. Ведутся только в ролевой форме: всё сказанное считается словами персонажа и истолковывается соответственно. Форматов три:</p>" +
        "<ol><li><b>Личная переписка.</b> Начинается словами «Начало переговоров» и ответом «Подтверждаю» от каждого. После ролевого обмена итог записывается так: «В результате переговоров стороны сошлись на следующих условиях: …», и каждый снова пишет «подтверждаю». Затем один из участников (лучше несколько, если есть сомнения в полноте) передаёт администрации скриншоты. С этого момента переговоры действительны.</li>" +
        "<li><b>Беседа с участием администрации.</b> Администрация присутствует и ведёт переговоры. Нужна заявка в форме.</li>" +
        "<li><b>Голосовые переговоры.</b> Ведутся под запись в присутствии администрации. Это самый трудоёмкий вариант. Нужна заявка в форме; возможны переносы и отмена, потому что всё упирается в занятость администрации и игроков.</li></ol>" },

      { id: "summits", title: "Съезды и конференции", html:
        "<p>Съезд или глобальная конференция — крупное игровое событие из трёх частей: подготовка места, несколько сессий переговоров и вторичные события (празднества и т.п.). Здесь послы игроков и ГМ-государств решают общие вопросы: ограничение вооружений, границы, судьба проигравшего государства. Это же отличная возможность для провокаций, закулисных игр и знакомства с конкурентами.</p>" +
        "<p>Созвать такое событие может тот, кто подтвердит, что имеет на это право. Подходит любое из условий:</p>" +
        "<ul><li>Вы — уполномоченный представитель союза или иного объединения, где договором предусмотрены периодические съезды. Тогда можно созывать очередные и внеочередные.</li>" +
        "<li>Вы председатель конференции и по договору вправе созвать её вне очереди.</li>" +
        "<li>Вы провели отдельные переговоры со всеми будущими участниками и получили подтверждение участия, то есть собрали конференцию вручную.</li></ul>" },

      { id: "ultimatums", title: "Ультиматумы", html:
        "<p>Ультиматум — сессия переговоров без самих переговоров. Одна сторона выдвигает условия, которые нельзя оспорить или изменить, если сам ультиматум этого не допускает. К ним прилагаются последствия отказа, чаще всего объявление войны.</p>" +
        "<p>Получатель может только принять или отклонить. В обоих случаях составляется договор со всеми условиями ультиматума. Получивший ультиматум всё же вправе попытаться отменить его через переговоры.</p>" },

      { id: "orgs", title: "Международные организации", html:
        "<p>Международная организация — объединение, признанное частью мирового сообщества, с функциями и полномочиями, определёнными договором. Создаётся в рамках союза или отдельным соглашением. Будет ли организация работать на территории государства и в отношении его граждан, решает правительство этого государства.</p>" +
        "<p>При создании обязательно прописываются три вещи:</p>" +
        "<ol><li>Договор об учреждении (или аналогичное объявление, если организацию пока никто не поддержал). Оформляется по шаблону обычного договора.</li>" +
        "<li>Перечень функций: зачем она нужна тем, кто захочет к ней обратиться.</li>" +
        "<li>Перечень полномочий и свобод, которые государство ей предоставляет для этих функций.</li></ol>" +
        "<p>Примеры: гуманитарные организации, помогающие бедным странам, международные полицейские структуры, суды, устанавливающие факты и наказания за преступления высших должностных лиц. Вес любой такой организации определяется числом государств, которые её поддерживают, подписали её договор, пользуются её услугами и дают ей полномочия.</p>" },

      { id: "indicators", title: "Сводка показателей", html:
        "<p>Ниже — все величины, на которых держится внешняя политика. Колонка «В механиках» показывает, определено ли значение в других статьях или его нужно ввести как новый показатель государства.</p>" +
        T(["Показатель", "Что означает", "Где используется", "В механиках"], [
          ["<b>Влиятельность</b>", "Очки международного влияния; тратятся на все действия в конфронтации", "Требования, приглашения, вступление третьих сторон", "нужно ввести"],
          ["<b>АВ</b>", "Административное влияние: 1 за требование, 2 за приглашение", "Все действия фаз", "есть (Государство, Экономика)"],
          ["<b>Государственное присутствие</b>", "Доля от 0 до 1 (50% = 0,5), в которой государство присутствует в области конфронтации; ×10 даёт от 0 до 10 баллов начального баланса", "Начальный баланс", "нужно ввести"],
          ["<b>Мировая поддержка</b>", "Отношение мирового сообщества к стороне, доля от 0 до 1; ×10 даёт от 0 до 10 баллов начального баланса", "Начальный баланс, баллы за переговоры", "нужно ввести"],
          ["<b>Баланс сил</b>", "От −100 до 100; побеждает достигший предела", "Расчёт конфронтации", "нужно ввести (на конфронтацию)"],
          ["<b>Усталость от конфронтации</b>", "В процентах; меняет шансы событий и стабильность", "Холодная, горячая фаза, война за ультиматум", "нужно ввести"],
          ["<b>Стабильность</b>", "Падает при усталости свыше 100% и в провинциях, затронутых войной", "Провинции", "есть (<a href=\"#wiki/mech/stability\">Стабильность</a>)"],
          ["<b>Лояльность групп населения</b>", "Страдает от негативных событий при высокой усталости", "Общество", "есть (Государство)"],
          ["<b>Организация армии</b>", "Повестка; задаёт цену потерь в баллах баланса", "Потери в бою", "есть (повестки)"],
          ["<b>ВВП и бюджет</b>", "Мерило успеха санкций", "Санкции", "есть (Экономика)"]
        ]) +
        GMN("Значения баллов взяты из исходного текста. Цены влиятельности (5 за требование, 5 за приглашение) предложены редактором и приняты автором. Откуда страна получает влиятельность, пока не определено.") }
    ]
  });

